using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.ComponentModel;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using Microsoft.Win32;

namespace PixelForge {
public sealed partial class MainWindow {
    BackgroundGalleryView gallery;ContentControl studioHost;TextBlock studioStatus=new TextBlock {MaxWidth=180,TextTrimming=TextTrimming.CharacterEllipsis,VerticalAlignment=VerticalAlignment.Center};
    string studioPath;bool studioDirty,studioBusy,studioTransition,studioRestoring,studioCloseApproved,studioClosing;
    public void MarkStudioDirty(){if(!studioRestoring)studioDirty=true;}
    bool StudioHasChanges {get{return studioDirty||changed||cutscenes.WorkspaceDirty||backgrounds.WorkspaceDirty;}}
    bool StudioWorking {get{return studioBusy||busy||cutscenes.WorkspaceWorking||backgrounds.WorkspaceWorking||gallery.IsWorking;}}
    void InitializeStudioShell(){
        Content=null;var root=new DockPanel {Background=Background};var toolbar=new WrapPanel {Margin=new Thickness(10,8,10,2)};DockPanel.SetDock(toolbar,Dock.Top);root.Children.Add(toolbar);
        ShellButton(toolbar,"Главная",()=>{ShowHome();return Task.FromResult(true);});ShellButton(toolbar,"Новый",NewStudio);ShellButton(toolbar,"Открыть",OpenStudioDialog);ShellButton(toolbar,"Сохранить",()=>SaveStudio(false));ShellButton(toolbar,"Сохранить как",()=>SaveStudio(true));ShellButton(toolbar,"Галерея",()=>{ShowWorkspace(3);gallery.Refresh();return Task.FromResult(true);});toolbar.Children.Add(studioStatus);
        gallery=new BackgroundGalleryView();gallery.OpenBackground=async p=>{if(StudioWorking)return;try{await backgrounds.FlushGallery();backgrounds.InstallWorkspace(p,true);MarkStudioDirty();ShowWorkspace(2);}catch(Exception ex){SetStudioStatus(ex.Message);}};gallery.UseBackground=(p,f)=>{cutscenes.AddAmbient(p,f);ShowWorkspace(1);};mainTabs.Items.Add(new TabItem {Header="04 · Галерея фонов",Content=gallery});
        cutscenes.WorkspaceEdited=MarkStudioDirty;backgrounds.WorkspaceEdited=MarkStudioDirty;
        studioHost=new ContentControl {Content=mainTabs};root.Children.Add(studioHost);Content=root;UpdateStudioTitle();
        BackgroundLibrary.Changed+=()=>{if(!Dispatcher.HasShutdownStarted)Dispatcher.BeginInvoke(new Action(gallery.Refresh));};
        Loaded+=async(s,e)=>{if(AutomatedTest)return;ShowHome();try{await Task.Run(()=>BackgroundLibrary.ImportExisting());gallery.Refresh();}catch(Exception ex){SetStudioStatus("Галерея: "+ex.Message);}};
        PreviewKeyDown+=async(s,e)=>{if((Keyboard.Modifiers&ModifierKeys.Control)==0)return;try{if(e.Key==Key.S){e.Handled=true;await SaveStudio((Keyboard.Modifiers&ModifierKeys.Shift)!=0);}if(e.Key==Key.O){e.Handled=true;await OpenStudioDialog();}if(e.Key==Key.N){e.Handled=true;await NewStudio();}}catch(Exception ex){SetStudioStatus(ex.Message);}};
    }
    void ShellButton(Panel p,string title,Func<Task<bool>> action){var button=new Button {Content=title,Padding=new Thickness(8,6,8,6),Margin=new Thickness(0,0,6,5)};button.Click+=async(s,e)=>{if(studioBusy||studioTransition)return;try{await action();}catch(Exception ex){SetStudioStatus(ex.Message);}};p.Children.Add(button);}
    void SetStudioStatus(string message){studioStatus.Text=message;studioStatus.ToolTip=message;}
    void UpdateStudioTitle(){string name=studioPath==null?"Новый проект":Path.GetFileNameWithoutExtension(studioPath);Title="PixelForge Studio · "+name;SetStudioStatus(name);}
    void PauseWorkspace(){clock.Stop();cutscenes.Stop();backgrounds.Stop();editor.FinishStroke();Keyboard.ClearFocus();}
    void ShowWorkspace(int tab){PauseWorkspace();studioHost.Content=mainTabs;mainTabs.SelectedIndex=Math.Max(0,Math.Min(3,tab));}
    void ShowHome(){if(studioBusy)return;PauseWorkspace();var root=new DockPanel {Margin=new Thickness(35)};var header=new StackPanel();DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);header.Children.Add(new TextBlock {Text="PIXELFORGE STUDIO",FontSize=34,FontWeight=FontWeights.Bold,Foreground=Brushes.MediumAquamarine});header.Children.Add(new TextBlock {Text="Спрайты, спокойные фоны и монтаж катсцен в одном проекте",FontSize=15,Foreground=Brushes.LightSlateGray,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,9,0,22)});var actions=new WrapPanel();header.Children.Add(actions);ShellButton(actions,"Новый проект",NewStudio);ShellButton(actions,"Открыть проект…",OpenStudioDialog);if(studioPath!=null||StudioHasChanges)ShellButton(actions,"Продолжить текущий",()=>{ShowWorkspace(1);return Task.FromResult(true);});ShellButton(actions,"Галерея фонов",()=>{ShowWorkspace(3);gallery.Refresh();return Task.FromResult(true);});header.Children.Add(new TextBlock {Text="НЕДАВНИЕ ПРОЕКТЫ",FontSize=15,FontWeight=FontWeights.Bold,Margin=new Thickness(0,26,0,14)});
        var list=new StackPanel();foreach(var recent in RecentProjects.List()){var body=new Grid {Margin=new Thickness(14)};body.ColumnDefinitions.Add(new ColumnDefinition {Width=new GridLength(1,GridUnitType.Star)});body.ColumnDefinitions.Add(new ColumnDefinition {Width=GridLength.Auto});var text=new StackPanel();text.Children.Add(new TextBlock {Text=recent.Name,FontSize=18,FontWeight=FontWeights.Bold});text.Children.Add(new TextBlock {Text=recent.Path,Foreground=Brushes.LightSlateGray,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,5,15,0)});bool exists=File.Exists(recent.Path);if(!exists)text.Children.Add(new TextBlock {Text="Файл перемещён или недоступен",Foreground=Brushes.Orange,Margin=new Thickness(0,6,0,0)});body.Children.Add(text);var open=new Button {Content="Открыть",IsEnabled=exists,VerticalAlignment=VerticalAlignment.Center};Grid.SetColumn(open,1);body.Children.Add(open);string file=recent.Path;open.Click+=async(s,e)=>{if(studioBusy||studioTransition)return;await OpenStudio(file);};list.Children.Add(new Border {Background=new SolidColorBrush(Color.FromRgb(29,37,52)),CornerRadius=new CornerRadius(4),Margin=new Thickness(0,0,0,10),Child=body});}
        if(list.Children.Count==0)list.Children.Add(new TextBlock {Text="Здесь появятся проекты после первого сохранения или открытия .pfstudio.",TextWrapping=TextWrapping.Wrap,Foreground=Brushes.LightSlateGray});root.Children.Add(new ScrollViewer {Content=list,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled});studioHost.Content=root;
    }
    void StudioBusy(bool value){studioBusy=value;studioHost.IsEnabled=!value;}
    async Task<bool> ConfirmWorkspace(){PauseWorkspace();if(!StudioHasChanges)return true;var answer=MessageBox.Show("Сохранить весь текущий проект Studio перед продолжением?","PixelForge Studio",MessageBoxButton.YesNoCancel);if(answer==MessageBoxResult.Cancel)return false;return answer!=MessageBoxResult.Yes||await SaveStudio(false);}
    StudioState CaptureStudio(){
        var scene=cutscenes.CaptureWorkspace();var bg=backgrounds.CaptureWorkspace();var state=new StudioState {Scene=scene,Background=bg,VideoPath=videoPath};state.Manifest.ActiveTab=mainTabs.SelectedIndex;state.Manifest.Name=studioPath==null?"Новый проект":Path.GetFileNameWithoutExtension(studioPath);state.Manifest.Sprites=CaptureSprites();cutscenes.CaptureWorkspaceView(state.Manifest);backgrounds.CaptureWorkspaceView(state.Manifest);var ids=scene.Layers.Select(l=>l.BackgroundLibraryId).Where(id=>!string.IsNullOrEmpty(id)).ToList();if(bg.Base!=null&&!string.IsNullOrEmpty(bg.LibraryId))ids.Add(bg.LibraryId);var available=BackgroundLibrary.List();foreach(string id in ids.Distinct()){if(available.Any(e=>e.Id==id))state.Library[id]=BackgroundLibrary.Load(id);}
        if(scene.Layers.Count>0)state.Preview=SceneRenderer.Render(scene,0);else if(bg.Base!=null)state.Preview=bg.Base;else if(frames.Count>0)state.Preview=frames[0];return state;
    }
    async Task<bool> SaveStudio(bool saveAs){if(StudioWorking){SetStudioStatus("Сначала завершите текущую обработку или экспорт.");return false;}PauseWorkspace();string file=studioPath;if(saveAs||file==null){var dialog=new SaveFileDialog {Filter="Проект PixelForge Studio|*.pfstudio",FileName=file??"project.pfstudio"};if(dialog.ShowDialog()!=true)return false;file=dialog.FileName;}try{StudioBusy(true);SetStudioStatus("Сохраняю весь проект…");await backgrounds.FlushGallery();var state=CaptureStudio();state.Manifest.Name=Path.GetFileNameWithoutExtension(file);await Task.Run(()=>StudioFile.Save(state,file));studioPath=file;changed=false;cutscenes.MarkWorkspaceSaved();backgrounds.MarkWorkspaceSaved();studioDirty=false;RecentProjects.Touch(file);UpdateStudioTitle();SetStudioStatus("Сохранён: "+Path.GetFileName(file));return true;}catch(Exception ex){SetStudioStatus("Сохранение: "+ex.Message);if(!AutomatedTest)MessageBox.Show(ex.Message,"Не удалось сохранить проект");return false;}finally{StudioBusy(false);}}
    async Task<bool> OpenStudioDialog(){var dialog=new OpenFileDialog {Filter="Проект PixelForge Studio|*.pfstudio"};return dialog.ShowDialog()==true&&await OpenStudio(dialog.FileName);}
    async Task<bool> OpenStudio(string file){if(StudioWorking||studioTransition){SetStudioStatus("Сначала завершите текущую обработку.");return false;}studioTransition=true;try{if(!await ConfirmWorkspace())return false;StudioBusy(true);SetStudioStatus("Открываю проект и встроенные ресурсы…");await backgrounds.FlushGallery();var state=await Task.Run(()=>StudioFile.Load(file));var remap=new Dictionary<string,string>();foreach(var pair in state.Library){pair.Value.LibraryId=pair.Key;var item=await Task.Run(()=>BackgroundLibrary.Upsert(pair.Value,true));remap[pair.Key]=item.Id;}if(state.Background.LibraryId!=null&&remap.ContainsKey(state.Background.LibraryId))state.Background.LibraryId=remap[state.Background.LibraryId];foreach(var layer in state.Scene.Layers)if(layer.BackgroundLibraryId!=null&&remap.ContainsKey(layer.BackgroundLibraryId))layer.BackgroundLibraryId=remap[layer.BackgroundLibraryId];
            string previousVideo=videoPath;studioRestoring=true;try{InstallSprites(state.Manifest.Sprites);cutscenes.InstallWorkspace(state.Scene);backgrounds.InstallWorkspace(state.Background);cutscenes.RestoreWorkspaceView(state.Manifest);backgrounds.RestoreWorkspaceView(state.Manifest);videoPath=state.VideoPath;if(videoPath!=null)try{await LoadVideo(videoPath);}catch{player.Close();}studioPath=Path.GetFullPath(file);studioDirty=false;changed=false;cutscenes.MarkWorkspaceSaved();backgrounds.MarkWorkspaceSaved();ShowWorkspace(state.Manifest.ActiveTab);}finally{studioRestoring=false;}StudioFile.CleanupVideo(previousVideo);RecentProjects.Touch(file);UpdateStudioTitle();SetStudioStatus("Открыт: "+Path.GetFileName(file));gallery.Refresh();return true;
        }catch(Exception ex){SetStudioStatus("Открытие: "+ex.Message);if(!AutomatedTest)MessageBox.Show(ex.Message,"Не удалось открыть проект");return false;}finally{studioTransition=false;StudioBusy(false);}}
    async Task<bool> NewStudio(){if(StudioWorking||studioTransition)return false;studioTransition=true;try{if(!await ConfirmWorkspace())return false;await backgrounds.FlushGallery();string previousVideo=videoPath;studioRestoring=true;try{InstallSprites(new SpriteWorkspace());cutscenes.InstallWorkspace(new Cutscene());backgrounds.InstallWorkspace(new AmbientProject());studioPath=null;studioDirty=false;changed=false;ShowWorkspace(1);UpdateStudioTitle();StudioFile.CleanupVideo(previousVideo);}finally{studioRestoring=false;}return true;}finally{studioTransition=false;}}
    async void OnStudioClosing(CancelEventArgs e){if(AutomatedTest){player.Close();return;}if(studioCloseApproved){player.Close();return;}e.Cancel=true;if(studioClosing||StudioWorking){SetStudioStatus("Сначала завершите обработку или отмените экспорт.");return;}studioClosing=true;try{if(!await ConfirmWorkspace())return;await backgrounds.FlushGallery();player.Close();await Task.Delay(80);StudioFile.CleanupVideo(videoPath);studioCloseApproved=true;Dispatcher.BeginInvoke(new Action(Close));}catch(Exception ex){SetStudioStatus(ex.Message);}finally{studioClosing=false;}}
}
}




